import { DiceBonus } from './dice-bonus.model';
import { ActionMacro } from './action-macro.model';


/**
 * Status Effect - A condition that can be applied to characters
 * Can affect stats, provide bonuses/penalties, and trigger macro actions
 */
export interface StatusEffect {
  id: string;
  name: string;
  description: string;
  
  // Visual
  icon?: string; // Emoji or icon identifier
  color?: string; // Hex color for the status effect tile
  
  // Mechanical effects
  diceBonuses?: DiceBonus[]; // Bonuses or penalties to dice rolls
  statModifiers?: StatusStatModifier[]; // Direct stat modifications
  talentModifiers?: StatusTalentModifier[]; // Modifiers to specific Talent-Modifikatoren

  /**
   * Cleanse difficulty — how hard this effect is to remove. Purely informational for
   * players (shown on the status display); does not affect stats.
   */
  strength?: number;

  // Macro integration
  macroActionId?: string;      // Legacy: ID of a library MacroAction
  embeddedMacro?: ActionMacro; // Inline ActionMacro (copied, not referenced)
  embeddedMacros?: ActionMacro[]; // Multiple macros that all trigger when the effect fires
  script?: string;             // FailScript action (new); takes precedence over embeddedMacro(s)

  /**
   * Ordering priority for this effect's `effectActive` stat modifiers in the stat pipeline.
   * Lower runs first, higher last — so e.g. a `speed *= 2` on a high-priority effect applies
   * after additive `speed += 2` from a low-priority one. Defaults to 0.
   */
  priority?: number;

  // Duration & stacking
  defaultDuration?: number; // Default duration in turns/rounds
  maxStacks?: number; // Maximum number of times this effect can stack
  isDebuff?: boolean; // Whether this is a negative effect
  
  // Visibility
  public?: boolean; // If true, all characters can always see and add this effect from their sheet

  // Metadata
  tags?: string[]; // Categorization (e.g., 'poison', 'buff', 'curse')
}

/**
 * Targets a status effect stat modifier can apply to.
 *  - Base stats: strength…chill
 *  - Resources: life / energy / mana
 *  - Derived values: fokus, armorMalus (Rüstungsmalus), armorNegation (Rüstungsnegation),
 *    grundbonus, reaktion (Reaktionsbonus), bewegung (flat movement, added to movement
 *    steps directly — NOT to speed).
 */
export type StatusModifierTarget =
  | 'strength' | 'dexterity' | 'speed' | 'intelligence' | 'constitution' | 'chill'
  | 'life' | 'energy' | 'mana'
  | 'fokus' | 'armorMalus' | 'armorNegation' | 'grundbonus' | 'reaktion' | 'bewegung'
  | 'stability';

/**
 * Stat modifier applied by a status effect
 */
export interface StatusStatModifier {
  stat: StatusModifierTarget;
  amount: number; // Can be negative for debuffs
  isPercentage?: boolean; // If true, apply as percentage instead of flat amount
}

/**
 * Modifier a status effect applies to a specific Talent's Würfelbonus (Talent-Modifikator).
 * Positive `amount` makes the roll easier (like an invested rank).
 */
export interface StatusTalentModifier {
  talentId: string;
  amount: number;
}

/**
 * Active status effect on a character
 * Tracks instance-specific data like duration and stacks
 */
export interface ActiveStatusEffect {
  statusEffectId: string; // References the base status effect
  sourceLibraryId: string; // Which library this came from
  
  // Instance data
  appliedAt: number; // Timestamp
  appliedBy?: string; // Character ID or GM
  duration?: number; // Remaining duration (overrides default)
  stacks: number; // Current stack count
  
  // Optional overrides
  customName?: string; // Override the base name
  customDescription?: string; // Override the base description
  customDiceBonuses?: DiceBonus[]; // Override dice bonuses
  
  // Custom effect (breaks library link when edited)
  customEffect?: StatusEffect; // If present, use this instead of library definition
}

/**
 * Create a new status effect
 */
export function createEmptyStatusEffect(): StatusEffect {
  return {
    id: `status_${Date.now()}_${Math.random().toString(36).substring(2, 9)}`,
    name: 'New Status Effect',
    description: '',
    diceBonuses: [],
    statModifiers: [],
    tags: [],
    isDebuff: false,
    maxStacks: 1,
    public: false,
  };
}

/**
 * Apply a status effect to a character (creates ActiveStatusEffect)
 */
export function applyStatusEffect(
  statusEffect: StatusEffect,
  sourceLibraryId: string,
  appliedBy?: string
): ActiveStatusEffect {
  return {
    statusEffectId: statusEffect.id,
    sourceLibraryId,
    appliedAt: Date.now(),
    appliedBy,
    duration: statusEffect.defaultDuration,
    stacks: 1
  };
}
